alter table public.listening_clips
  add column if not exists annotation text not null default 'none'
  check (annotation in ('none', 'zhuyin', 'pinyin'));

-- For zhuyin this is the transcript with variation selectors woven in; for
-- pinyin it is a JSON array of per-character syllables the page renders as ruby.
-- Kept apart from `transcript` so the teacher can still edit plain text and
-- re-annotate without losing their wording.
alter table public.listening_clips
  add column if not exists annotation_text text null;

-- The same text cut into words, each with its 正詞法 spelling. annotation_text
-- above is one syllable per character, which is what a flashcard wants; a
-- reader wants words, so that 星期六 is xīngqīliù rather than xīng qí liù and
-- 小明 is capitalised. Both come back from one annotate-reading call.
alter table public.listening_clips
  add column if not exists annotation_words jsonb null;

-- The subset built for exactly this clip's characters. Null for pinyin, which
-- needs no font at all.
alter table public.listening_clips
  add column if not exists font_path text null;

alter table public.listening_clips
  add column if not exists font_url text null;

-- Generated once with the audio, then copied only to an audio-only question.
-- Listening quizzes keep both this and the transcript private.
alter table public.listening_clips
  add column if not exists karaoke_cues jsonb not null default '[]'::jsonb
  check (jsonb_typeof(karaoke_cues) = 'array');

create index if not exists listening_clips_session_idx
  on public.listening_clips (session_id, created_at desc);

create unique index if not exists listening_clips_reuse_idx
  on public.listening_clips (session_id, content_hash);

-- Reading aloud is the mirror image of a listening test: the learner must see
-- the very text a listening question hides. So the words and the font travel on
-- the question, which students may read, instead of on the clip, whose
-- transcript and font are granted to nobody.
--
-- The font matters as much as the text. A subset is cut from exactly the
-- characters of one clip, so handing it out for a listening item would leak
-- which characters the passage uses. On a read-aloud item there is nothing left
-- to leak — the text is on screen.
alter table public.questions
  add column if not exists reading_font_url text null;

-- Character/word spans on prompt_text, measured against the stored recording.
-- currentTime remains media time at every playbackRate, so slow playback needs
-- no second set of timestamps.
alter table public.questions
  add column if not exists karaoke_cues jsonb not null default '[]'::jsonb
  check (jsonb_typeof(karaoke_cues) = 'array');

-- Timed activities: a countdown to think, then a countdown to answer.
--
-- Two fields rather than one because the pause before speaking is the exercise
-- in a spoken challenge — twenty seconds to plan, thirty to say it — while a
-- vocabulary race has no preparation at all, only a clock.
--
-- Null means untimed, which is what every existing question is and should stay.
alter table public.questions
  add column if not exists prepare_seconds integer null
  check (prepare_seconds is null or prepare_seconds between 5 and 300);

alter table public.questions
  add column if not exists answer_seconds integer null
  check (answer_seconds is null or answer_seconds between 5 and 600);

-- Null means unlimited, which is right for practice and wrong for a test: a
-- listening assessment a student can replay until they have transcribed it is
-- a reading assessment.
alter table public.questions
  add column if not exists replay_limit integer null check (replay_limit is null or replay_limit between 1 and 10);

-- How many points one student may drop on a 圖上點選 image. Null everywhere else.
alter table public.questions
  add column if not exists max_pins integer null;
do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.questions'::regclass and conname = 'questions_max_pins_check'
  ) then
    alter table public.questions
      add constraint questions_max_pins_check
      check (max_pins is null or max_pins between 1 and 10);
  end if;
end $$;

-- questions_type_check is defined once, further down, with every type in it.
-- It used to be defined here as well, without 'board' — and a constraint is
-- checked against the rows already in the table, so on any database that had
-- ever opened a discussion board this line failed with 23514 and took the whole
-- transaction with it. The narrow definition is gone rather than widened:
-- two definitions of one constraint only ever means the earlier one is waiting
-- to reject data the app has since learned to write.

do $$
begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'listening_clips'
  ) then
    alter publication supabase_realtime add table public.listening_clips;
  end if;
end $$;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
-- The per-clip font subset lives beside the audio it belongs to: same clip,
-- same lifetime, deleted together when the session goes.
values ('lingoact-listening', 'lingoact-listening', true, 10485760, array['audio/wav', 'font/woff2']::text[])
on conflict (id) do update set
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

insert into storage.buckets (id, name, public)
values ('lingoact-screenshots', 'lingoact-screenshots', true)
on conflict (id) do update set public = excluded.public;

insert into storage.buckets (id, name, public)
values ('lingoact-files', 'lingoact-files', true)
on conflict (id) do update set public = excluded.public;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('lingoact-recordings', 'lingoact-recordings', false, 10485760, array['audio/wav']::text[])
on conflict (id) do update set
  public = excluded.public,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

-- PostgREST answers from a cached copy of the schema, so a column added above is
-- invisible until it reloads — the app would keep reporting PGRST204 for a column
-- that already exists.
notify pgrst, 'reload schema';

-- Dragging fragments into order: one primitive, three activities (故事排序,
-- 句子重組, and the ordering half of a listening task).
alter table public.quiz_items drop constraint if exists quiz_items_type_check;
alter table public.quiz_items
  add constraint quiz_items_type_check
  check (type in ('multiple_choice', 'fill_blank', 'short_answer', 'ordering', 'matching'));

alter table public.quiz_items
  add column if not exists pair_prompts jsonb not null default '[]'::jsonb;

alter table public.quiz_items
  add column if not exists option_images jsonb not null default '[]'::jsonb;

-- 單字卡 標音, beside the option rather than inside it: options is what the
-- answer is compared against, so annotating it in place would leave a card whose
-- correct answer no longer matches its own key.
alter table public.quiz_items
  add column if not exists option_readings jsonb not null default '[]'::jsonb;

alter table public.quiz_items
  add column if not exists prompt_is_word boolean not null default false;

alter table public.quiz_items
  add column if not exists prompt_reading text null;

-- Generated once with the deck and served from Storage thereafter. Keeping the
-- URL on the public card row means thirty students pressing the speaker do not
-- turn into thirty speech-model calls.
alter table public.quiz_items
  add column if not exists audio_url text null;

alter table public.quiz_items
  add column if not exists audio_status text not null default 'pending'
  check (audio_status in ('pending', 'processing', 'ready'));

-- One font subset for the whole deck, cut from the characters its cards use.
alter table public.questions
  add column if not exists card_font_url text null;

-- Ten is a long quiz but a short 生詞表, and a deck can now be added to after
-- the teacher has seen what the AI made of it.
alter table public.quiz_items drop constraint if exists quiz_items_position_check;
alter table public.quiz_items
  add constraint quiz_items_position_check check (position between 1 and 30);
alter table public.quizzes drop constraint if exists quizzes_requested_count_check;
alter table public.quizzes
  add constraint quizzes_requested_count_check
  check (requested_count is null or requested_count between 1 and 30);

notify pgrst, 'reload schema';

alter table public.quizzes drop constraint if exists quizzes_requested_type_check;
alter table public.quizzes
  add constraint quizzes_requested_type_check
  check (requested_type in (
    'random', 'multiple_choice', 'fill_blank', 'short_answer',
    'ordering', 'matching', 'writing', 'flashcard', 'picture_ordering', 'picture_writing'
  ));

alter table public.quizzes
  add column if not exists graded boolean not null default true;

alter table public.quiz_attempts drop constraint if exists quiz_attempts_status_check;
alter table public.quiz_attempts
  add constraint quiz_attempts_status_check
  check (status in ('grading', 'graded', 'submitted', 'failed'));

notify pgrst, 'reload schema';

-- Screenshot ordering/matching uses the existing private quiz keys and attempts.
alter table public.quizzes add column if not exists interaction_mode boolean not null default false;
alter table public.quiz_items add column if not exists sentence_mode boolean not null default false;

-- Keep every practice round as its own question, with an explicit parent.
alter table public.questions add column if not exists source_question_id uuid references public.questions(id) on delete set null;
alter table public.questions add column if not exists learning_focus text;
alter table public.questions add column if not exists teaching_mode text;
alter table public.questions add column if not exists discussion_samples jsonb not null default '[]'::jsonb;

-- A/B material must never be placed on the publicly readable questions row.
create table if not exists public.teaching_pairs (
  id uuid primary key default gen_random_uuid(),
  question_id uuid not null references public.questions(id) on delete cascade,
  participant_a uuid not null references public.participants(id) on delete cascade,
  participant_b uuid references public.participants(id) on delete cascade,
  material_a text not null,
  material_b text not null,
  result text,
  submitted_by uuid references public.participants(id) on delete set null,
  submitted_at timestamptz,
  unique(question_id, participant_a)
);
alter table public.teaching_pairs enable row level security;
revoke all on public.teaching_pairs from public, anon, authenticated;
grant all on public.teaching_pairs to service_role;

-- Publish only after all copied quiz rows or pair assignments are ready.
create or replace function public.publish_teaching_question(target_session uuid, target_question uuid, expected_current uuid)
returns void language plpgsql set search_path = public as $$
declare current_id uuid; session_status text;
begin
  select current_question_id, status into current_id, session_status from sessions where id = target_session for update;
  if session_status is distinct from 'active' or current_id is distinct from expected_current then
    raise exception 'Class changed. Reload before dispatching.';
  end if;
  if not exists(select 1 from questions where id = target_question and session_id = target_session and status = 'draft') then
    raise exception 'Draft question not found.';
  end if;
  update questions set status = 'stopped', stopped_at = now() where session_id = target_session and status = 'active';
  update questions set status = 'active', started_at = now(), stopped_at = null where id = target_question;
  update sessions set current_question_id = target_question where id = target_session;
end;
$$;
revoke all on function public.publish_teaching_question(uuid, uuid, uuid) from public, anon, authenticated;
grant execute on function public.publish_teaching_question(uuid, uuid, uuid) to service_role;
create or replace function public.submit_teaching_pair(target_question uuid, learner uuid, shared_result text)
returns void language plpgsql set search_path = public as $$
declare q questions%rowtype; p teaching_pairs%rowtype;
begin
  select * into q from questions where id = target_question for update;
  if q.status is distinct from 'active' or not exists(select 1 from sessions where id=q.session_id and status='active') then
    raise exception 'Answering has stopped.';
  end if;
  select * into p from teaching_pairs where question_id=target_question and (participant_a=learner or participant_b=learner) for update;
  if p.id is null or p.submitted_at is not null or length(trim(shared_result)) not between 1 and 4000 then
    raise exception 'Pair not found, already submitted, or empty result.';
  end if;
  update teaching_pairs set result=trim(shared_result), submitted_by=learner, submitted_at=now() where id=p.id;
  insert into answers(session_id, question_id, participant_id, participant_name, answer_text)
    select q.session_id, q.id, id, name, trim(shared_result) from participants where id in (p.participant_a,p.participant_b)
    on conflict (question_id, participant_id) do update set answer_text=excluded.answer_text;
end;
$$;
revoke all on function public.submit_teaching_pair(uuid, uuid, text) from public, anon, authenticated;
grant execute on function public.submit_teaching_pair(uuid, uuid, text) to service_role;
notify pgrst, 'reload schema';

-- ============================ 討論板 ============================
--
-- The same dispatch 派送畫面 has always been, with replies switched on: the
-- class puts cards on a wall instead of answering into a box, and can answer
-- each other. Everything below sits at the end of the file because the whole
-- file is one transaction — a statement above its own table empties a new
-- project rather than failing on its own.

alter table public.questions
  -- Which kinds of card the class may put on the board: any of 'text', 'link',
  -- 'image', 'file', 'audio', 'drawing'. Empty means the screen was dispatched
  -- with nothing to answer, which is the plain 派送畫面 it has always been.
  add column if not exists board_formats text[] not null default '{}'::text[],
  -- How many cards one student may put up. Null is the infinity option, and is
  -- the reason this is nullable rather than a large number: the presenter picks
  -- 1, 2, 3, 5 or ∞, and ∞ has to mean it.
  add column if not exists board_max_posts integer null,
  -- When the class could see each other's cards. Normally set the moment the
  -- board is dispatched, because a wall everyone can see is what a wall is for.
  -- Null means the presenter asked for 自行作答: each student sees only their
  -- own until the board is opened. Reversible in both directions — a presenter
  -- may want the class to think alone first and then look, or to share from the
  -- start and then close it again to settle everyone down.
  add column if not exists board_revealed_at timestamptz null;

alter table public.questions drop constraint if exists questions_board_max_posts_check;
alter table public.questions
  add constraint questions_board_max_posts_check
  check (board_max_posts is null or board_max_posts between 1 and 50);

alter table public.questions drop constraint if exists questions_type_check;
alter table public.questions
  add constraint questions_type_check
  check (type in (
    'send_screen', 'poll', 'multiple_choice', 'true_false', 'short_answer',
    'pronunciation', 'oral_response', 'custom_quiz', 'file_upload', 'listening',
    'drawing', 'hotspot', 'board', 'reading'
  ));

-- Which board the class is on, which outlives the current question: a board
-- stays open while the lesson moves on to something else.
alter table public.sessions
  add column if not exists board_question_id uuid null;
alter table public.sessions
  drop constraint if exists sessions_board_question_id_fkey;
alter table public.sessions
  add constraint sessions_board_question_id_fkey
  foreign key (board_question_id) references public.questions(id)
  on delete set null;

-- Cards on a 討論板. One row is one thing a student put on the wall.
create table if not exists public.board_posts (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.sessions(id) on delete cascade,
  question_id uuid not null references public.questions(id) on delete cascade,
  participant_id uuid not null references public.participants(id) on delete cascade,
  participant_name text not null,
  kind text not null check (kind in ('text', 'link', 'image', 'file', 'audio', 'drawing')),
  -- The words on the card: the note itself, or the caption under a photograph.
  body text null,
  url text null,
  storage_path text null,
  mime_type text null,
  file_size bigint null check (file_size is null or file_size between 1 and 209715200),
  duration_ms integer null check (duration_ms is null or duration_ms between 250 and 300000),
  -- A reply to another card. Replies do not count against the per-student
  -- limit: that limit is how many contributions to the topic one student may
  -- make, and a class where answering someone costs you your own card is not a
  -- discussion. Replies are only possible after the board is revealed, because
  -- before that there is nothing to reply to.
  reply_to uuid null references public.board_posts(id) on delete cascade,
  -- Whether the class saw a name on this card, decided when it was written.
  -- Kept per row rather than read from the session, so turning anonymity off
  -- later cannot retroactively put names on cards written under it.
  anonymous_at_display boolean not null default true,
  -- The student took their own card back down. Kept rather than deleted so the
  -- report still shows it was written, and so the per-student count cannot be
  -- reset by deleting and reposting.
  deleted_at timestamptz null,
  -- The student corrected their own card. Recorded so the wall can say a card
  -- was changed after the class read it, rather than quietly showing different
  -- words to whoever looks next.
  edited_at timestamptz null,
  -- The presenter took it down for everyone.
  hidden_at timestamptz null,
  -- The presenter pushed it to the front of the wall.
  pinned_at timestamptz null,
  created_at timestamptz not null default now()
);

create index if not exists board_posts_question_idx on public.board_posts (question_id, created_at);
create index if not exists board_posts_participant_idx on public.board_posts (question_id, participant_id);
create index if not exists board_posts_reply_idx on public.board_posts (reply_to);

-- Who liked what. One row per student per card per emoji, so the primary key
-- does the de-duplication and a second tap is an ordinary delete.
create table if not exists public.board_reactions (
  post_id uuid not null references public.board_posts(id) on delete cascade,
  participant_id uuid not null references public.participants(id) on delete cascade,
  session_id uuid not null references public.sessions(id) on delete cascade,
  emoji text not null check (char_length(emoji) between 1 and 8),
  created_at timestamptz not null default now(),
  primary key (post_id, participant_id, emoji)
);

create index if not exists board_reactions_session_idx on public.board_reactions (session_id);

alter table public.board_posts enable row level security;
alter table public.board_reactions enable row level security;

-- A board card is readable by the class only once the presenter has revealed
-- the board. Enforced here rather than in the page, because 先遮後揭 stops
-- being worth anything the moment it is only a decision the client makes: a
-- student who reloads, or who looks at the network tab, would have the whole
-- wall. Before the reveal a student's own cards come back through
-- participant-action, which can prove who is asking; the presenter reads
-- everything through presenter-action on the service role, so the wall is
-- never hidden from the person running the class.
drop policy if exists "read a revealed board" on public.board_posts;
create policy "read a revealed board" on public.board_posts for select
to anon, authenticated
using (
  exists (
    select 1 from public.questions
    where questions.id = board_posts.question_id
      and questions.board_revealed_at is not null
  )
);

-- Both of these exist because a policy on board_posts cannot ask questions
-- about board_posts: the inner select is itself subject to the policy being
-- evaluated, and Postgres stops with "infinite recursion detected". A security
-- definer function runs as the owner and so is not re-checked. Neither returns
-- any content — one returns a count, the other a yes or no about whether a
-- card exists — so running them with the owner's rights gives nothing away.
create or replace function public.board_card_count(target_question uuid, target_participant uuid)
returns integer
language sql
security definer
stable
set search_path = public
as $board$
  select count(*)::int from public.board_posts
  where question_id = target_question
    and participant_id = target_participant
    and reply_to is null
    -- Deleting gives the card back. Counting deleted cards would stop nobody
    -- deleting their way past the limit but punishes the ordinary case: a
    -- student who posts, thinks better of it, and wants to say it properly.
    -- The limit is there to stop one person filling the wall, and a card that
    -- is not on the wall is not filling it.
    and deleted_at is null
$board$;

create or replace function public.board_parent_exists(target_question uuid, target_parent uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $board$
  select exists (
    select 1 from public.board_posts
    where id = target_parent
      and question_id = target_question
      and reply_to is null
  )
$board$;

grant execute on function public.board_card_count(uuid, uuid) to anon, authenticated;
grant execute on function public.board_parent_exists(uuid, uuid) to anon, authenticated;

drop policy if exists "post to an open board" on public.board_posts;
create policy "post to an open board" on public.board_posts for insert
to anon, authenticated
with check (
  exists (
    select 1 from public.questions q
    join public.sessions s on s.id = q.session_id
    where q.id = board_posts.question_id
      and q.session_id = board_posts.session_id
      and q.type = 'board'
      and q.status = 'active'
      and s.status = 'active'
      -- Only the kinds of card this board was opened for — and only for cards.
      -- The format list says how a student may ANSWER the topic; answering a
      -- classmate is a different act and is always words. Applying it to both
      -- meant that on a board opened for 電寫 alone, every reply was refused:
      -- a reply is text, text was not on the list, and the class was told
      -- 貼文失敗 with nothing to do about it.
      and (
        board_posts.reply_to is not null
        or board_posts.kind = any (q.board_formats)
      )
      -- A reply is text, on a card on this same board, and only once the board
      -- has been revealed — there is nothing to answer before that.
      and (
        board_posts.reply_to is null
        or (
          board_posts.kind = 'text'
          and q.board_revealed_at is not null
          and public.board_parent_exists(board_posts.question_id, board_posts.reply_to)
        )
      )
      -- The per-student limit, counted here rather than trusted from the page.
      -- Deleting frees a slot; see board_card_count. Replies are not counted,
      -- because a class where answering someone costs you your own card is not
      -- a discussion.
      and (
        board_posts.reply_to is not null
        or q.board_max_posts is null
        or public.board_card_count(board_posts.question_id, board_posts.participant_id) < q.board_max_posts
      )
  )
  and exists (
    select 1 from public.participants
    where participants.id = board_posts.participant_id
      and participants.session_id = board_posts.session_id
      and participants.name = board_posts.participant_name
  )
  -- A card has to be something. Which field carries it depends on the kind.
  and (
    case board_posts.kind
      when 'text' then char_length(btrim(coalesce(board_posts.body, ''))) between 1 and 1000
      when 'link' then char_length(btrim(coalesce(board_posts.url, ''))) between 4 and 2000
      else char_length(coalesce(board_posts.storage_path, '')) > 0
    end
  )
);

drop policy if exists "read reactions on a revealed board" on public.board_reactions;
create policy "read reactions on a revealed board" on public.board_reactions for select
to anon, authenticated
using (
  exists (
    select 1 from public.board_posts p
    join public.questions q on q.id = p.question_id
    where p.id = board_reactions.post_id and q.board_revealed_at is not null
  )
);

-- Editing, withdrawing, hiding, pinning and reacting all go through the edge
-- functions on the service role: each of them has to prove who is asking, and
-- a policy cannot. The class holds select and insert and nothing else.
grant select, insert on public.board_posts to anon, authenticated;
grant select on public.board_reactions to anon, authenticated;
grant all on public.board_posts, public.board_reactions to service_role;

do $$ begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'board_posts'
  ) then
    alter publication supabase_realtime add table public.board_posts;
  end if;
end $$;

do $$ begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'board_reactions'
  ) then
    alter publication supabase_realtime add table public.board_reactions;
  end if;
end $$;

-- ============================ 學生名單 ============================

alter table public.participants
  -- Removed from the list so they can rejoin under the right name. A student
  -- who typed something other than what is on the class list cannot fix it
  -- themselves: joining is keyed to the device, so every later attempt hands
  -- them back the first name they used.
  -- Which language this student is reading the page in. Stored so a dispatch
  -- can translate into the languages actually in the room and no others: the
  -- alternative is translating into all seven and paying for six nobody reads.
  add column if not exists locale text null,
  add column if not exists removed_at timestamptz null,
  -- Set when the student asks to be called on, cleared when the presenter
  -- acknowledges it. A timestamp rather than a flag so the class list can put
  -- the longest-waiting hand first.
  add column if not exists hand_raised_at timestamptz null;

-- Points the presenter gave out by hand, one row per award rather than a
-- running total on the participant: undoing a stray tap then removes the last
-- award instead of recording a negative one, so the total goes back to what it
-- was rather than reading as a punishment.
create table if not exists public.participant_points (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.sessions(id) on delete cascade,
  participant_id uuid not null references public.participants(id) on delete cascade,
  points integer not null default 1 check (points between 1 and 10),
  created_at timestamptz not null default now()
);

create index if not exists participant_points_session_idx
  on public.participant_points (session_id, participant_id);

alter table public.participant_points enable row level security;

drop policy if exists "mvp read participant points" on public.participant_points;
create policy "mvp read participant points" on public.participant_points for select using (true);

-- Awarding and revoking go through presenter-action on the service role, so
-- the class can read the tally and nothing else.
grant select on public.participant_points to anon, authenticated;
grant all on public.participant_points to service_role;

do $$ begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'participant_points'
  ) then
    alter publication supabase_realtime add table public.participant_points;
  end if;
end $$;

-- ================= 程式碼在用、schema 卻沒有的欄位 =================
--
-- Each of these is read or written by an edge function and existed in no
-- create table anywhere, so PostgREST answered the request with an error and
-- the student saw "Edge Function returned a non-2xx status code". Found by
-- scripts/check-schema-columns.mjs, which now runs in lint and CI so the next
-- one is caught before it reaches a class rather than during one.

-- 寫作教練: the finished article, as opposed to the per-section working-out
-- that lives in quiz_item_answers. participant-action writes it on submit and
-- the teaching cycle reads it to carry a student's own writing into the next
-- round.
alter table public.quiz_attempts
  add column if not exists composition text null;

-- The corrected article the AI hands back, which the student's page diffs
-- against what they wrote. { zh_tw, notes }.
alter table public.quiz_attempts
  add column if not exists revision jsonb null;

-- Whether a 討論板 shows the capture it was made from. Default true because a
-- board dispatched from a screenshot is about that screenshot, and nothing
-- writes the column — a board with no screenshot_id shows nothing regardless.
alter table public.questions
  add column if not exists share_screenshot boolean not null default true;

-- ============================ 閱讀與測驗 ============================
--
-- A passage written for the class's own level, with the words and grammar in
-- it that the class has not met yet marked up, and optionally a quiz over it.
-- The quiz half is an ordinary custom_quiz, so grading, 課堂紀錄 and 下一步教學
-- all work without knowing this feature exists.

alter table public.questions
  -- Whether the teacher asked to stretch the class: 0 stays inside the level,
  -- 1 and 2 are i+1 and i+2. It is stored because the annotations depend on it
  -- — which words counted as "not met yet" is a property of this dispatch.
  add column if not exists level_stretch integer not null default 0
  check (level_stretch between 0 and 2);

create table if not exists public.reading_passages (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.sessions(id) on delete cascade,
  question_id uuid not null references public.questions(id) on delete cascade,
  title text null,
  body text not null,
  -- Where the passage came from, so the teacher can tell a generated passage
  -- from one they pasted in.
  source text not null default 'ai' check (source in ('ai', 'pasted', 'screenshot')),
  -- [{ word, level, pos, gloss: { en, es, ... } }] — the words above the class’s
  -- ceiling. Marked by the word rather than by offset: a word that appears three
  -- times is new all three times, and offsets would have to be rebuilt every
  -- time the passage was edited.
  vocabulary jsonb not null default '[]'::jsonb,
  -- [{ point, level, example, span, note: { en, es, ... } }] — TBCL grammar
  -- points, named from the published list rather than invented, each carrying
  -- the exact stretch of the passage it applies to.
  grammar jsonb not null default '[]'::jsonb,
  -- Set when the teacher also had it read aloud; the clip lives in
  -- listening_clips like every other piece of speech in the app.
  listening_clip_id uuid null references public.listening_clips(id) on delete set null,
  -- The passage cut into words, each with its 漢語拼音正詞法 spelling:
  -- [{ text, pinyin }]. One segmentation decides both which words are new and
  -- how the readings are written, because 正詞法 spells a word rather than a
  -- character — zīliàojiā, not zī liào jiā.
  words jsonb not null default '[]'::jsonb,
  -- 注音 or 拼音 over the passage, in whichever system the class is set to.
  -- Both shapes are exactly the ones listening_clips already uses: zhuyin is
  -- the body with variation selectors woven in and needs the subset font,
  -- pinyin is a JSON array of syllables, one per character.
  annotation text not null default 'none' check (annotation in ('none', 'zhuyin', 'pinyin')),
  annotation_text text null,
  font_url text null,
  created_at timestamptz not null default now()
);

-- For projects deployed before the readings were put on the passage itself.
alter table public.reading_passages
  add column if not exists words jsonb not null default '[]'::jsonb,
  add column if not exists annotation text not null default 'none',
  add column if not exists annotation_text text null,
  add column if not exists font_url text null;

create unique index if not exists reading_passages_question_idx
  on public.reading_passages (question_id);

alter table public.reading_passages enable row level security;

-- A passage is the lesson itself, so the class reads it as soon as it is
-- dispatched — the same rule the screenshot follows.
drop policy if exists "read dispatched passages" on public.reading_passages;
create policy "read dispatched passages" on public.reading_passages for select to anon, authenticated using (
  exists (
    select 1 from public.questions
    where questions.id = reading_passages.question_id
      and questions.status in ('active', 'stopped', 'closed')
  )
);

grant select on public.reading_passages to anon, authenticated;
grant all on public.reading_passages to service_role;

do $$ begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'reading_passages'
  ) then
    alter publication supabase_realtime add table public.reading_passages;
  end if;
end $$;

-- 語法點說明. What 雖然…但是 does is the same sentence whatever passage it
-- appears in, so it is written once and kept. Before this it was generated with
-- every passage, in every language, which cost output tokens — the expensive
-- kind — on every dispatch and gave the same point a slightly different
-- explanation each time a class met it.
--
-- Not scoped to a session: a note about 把字句 belongs to the language, not to
-- one teacher's afternoon.
create table if not exists public.grammar_notes (
  point text not null,
  locale text not null,
  note text not null,
  -- The TBCL level, carried so a note can be shown with where it sits.
  level integer not null check (level between 1 and 7),
  created_at timestamptz not null default now(),
  primary key (point, locale)
);

alter table public.grammar_notes enable row level security;

drop policy if exists "read grammar notes" on public.grammar_notes;
create policy "read grammar notes" on public.grammar_notes for select to anon, authenticated using (true);

grant select on public.grammar_notes to anon, authenticated;
grant all on public.grammar_notes to service_role;
